import json
import re


PARAM_PATTERNS = {
    "equipment_count": r"(?:设备数量|设备数|台数|数量)\s*[:：]?\s*([0-9]+)\s*(?:台|套)?",
    "design_pressure": r"(?:设计压力|压力)\s*[:：]?\s*([0-9]+(?:\.[0-9]+)?)\s*(?:MPa|兆帕)?",
    "length": r"(?:长度|长)\s*[:：]?\s*([0-9]+(?:\.[0-9]+)?)\s*(?:mm|毫米)?",
    "width": r"(?:宽度|宽)\s*[:：]?\s*([0-9]+(?:\.[0-9]+)?)\s*(?:mm|毫米)?",
    "height": r"(?:高度|高)\s*[:：]?\s*([0-9]+(?:\.[0-9]+)?)\s*(?:mm|毫米)?",
}

KEYWORD_PATTERNS = [
    "干渣", "干式排渣", "炉渣", "底渣", "渣仓", "冷渣", "输渣",
    "设备数量", "设备数", "台数", "设计压力", "介质",
    "盒子", "方块", "长方体", "箱体", "长宽高", "box",
]


def _extract_parameters(text: str) -> dict:
    result = {}
    for code, pattern in PARAM_PATTERNS.items():
        match = re.search(pattern, text, re.IGNORECASE)
        if match:
            result[code] = match.group(1)
    return result


def _extract_keywords(text: str) -> list:
    seen = set()
    keywords = []
    for keyword in KEYWORD_PATTERNS:
        if keyword.lower() in text.lower() and keyword not in seen:
            keywords.append(keyword)
            seen.add(keyword)
    return keywords


def _strip_fence(text: str) -> str:
    text = (text or "").strip()
    match = re.match(r"^```[a-zA-Z0-9_-]*\s*(.*?)\s*```$", text, re.S)
    return match.group(1).strip() if match else text


def _load_llm_json(llm_text: str) -> dict:
    llm_text = _strip_fence(llm_text)
    if not llm_text:
        return {}
    try:
        data = json.loads(llm_text)
        return data if isinstance(data, dict) else {}
    except Exception:
        match = re.search(r"\{.*\}", llm_text, re.S)
        if match:
            try:
                data = json.loads(match.group(0))
                return data if isinstance(data, dict) else {}
            except Exception:
                return {}
        return {}


def main(
    query: str = "",
    ocr_text: str = "",
    target: str = "",
    instruction: str = "",
    llm_text: str = "",
) -> dict:
    parts = [query or "", ocr_text or "", target or "", instruction or ""]
    raw_text = "\n".join(part.strip() for part in parts if part and part.strip())

    llm_data = _load_llm_json(llm_text)
    llm_text_value = llm_data.get("text") if isinstance(llm_data.get("text"), str) else ""
    llm_keywords = llm_data.get("keywords") if isinstance(llm_data.get("keywords"), list) else []
    llm_parameters = (
        llm_data.get("extracted_parameters")
        if isinstance(llm_data.get("extracted_parameters"), dict)
        else {}
    )

    keywords = []
    for item in [*llm_keywords, *_extract_keywords(raw_text)]:
        if isinstance(item, str) and item and item not in keywords:
            keywords.append(item)

    extracted_parameters = _extract_parameters(raw_text)
    extracted_parameters.update(llm_parameters)

    signals = {
        "text": llm_text_value or raw_text,
        "keywords": keywords,
        "extracted_parameters": extracted_parameters,
    }

    query_blocks = [
        "任务: 在“Jiavu 参数化模型知识库”和 jiavu 知识图谱中检索候选参数化模型，并返回模型 ID、模型名称、template_name、适用条件和参数要求。",
        "需求文本:\n" + signals["text"],
        "关键词: " + "、".join(keywords),
        "已抽取参数: " + json.dumps(extracted_parameters, ensure_ascii=False, separators=(",", ":")),
    ]

    return {
        "retrieval_query": "\n\n".join(block for block in query_blocks if block.strip()),
        "signals_json": json.dumps(signals, ensure_ascii=False, separators=(",", ":")),
    }

