import json
import re


def _strip_fence(text: str) -> str:
    text = (text or "").strip()
    match = re.match(r"^```[a-zA-Z0-9_-]*\s*(.*?)\s*```$", text, re.S)
    return match.group(1).strip() if match else text


def _load_json(text: str) -> dict:
    text = _strip_fence(text)
    if not text:
        return {}
    try:
        data = json.loads(text)
        return data if isinstance(data, dict) else {}
    except Exception:
        match = re.search(r"\{.*\}", text, re.S)
        if not match:
            return {}
        try:
            data = json.loads(match.group(0))
            return data if isinstance(data, dict) else {}
        except Exception:
            return {}


def _as_dict(value) -> dict:
    return value if isinstance(value, dict) else {}


def _as_list(value) -> list:
    return value if isinstance(value, list) else []


def _string_dict(value) -> dict:
    if not isinstance(value, dict):
        return {}
    result = {}
    for key, item in value.items():
        if key is None:
            continue
        if isinstance(item, str):
            result[str(key)] = item
        else:
            result[str(key)] = json.dumps(item, ensure_ascii=False, separators=(",", ":"))
    return result


def _to_float(value, default=0.0) -> float:
    try:
        return float(value)
    except Exception:
        return default


def main(llm_text: str = "", signals_json: str = "") -> dict:
    data = _load_json(llm_text)
    signals = _load_json(signals_json)
    candidates = _as_list(data.get("candidates"))
    first_candidate = candidates[0] if candidates and isinstance(candidates[0], dict) else {}

    selected_model_id = (
        data.get("selected_model_id")
        or data.get("model_id")
        or first_candidate.get("model_id")
        or ""
    )
    selected_model = (
        data.get("selected_model")
        or data.get("model_name")
        or first_candidate.get("model_name")
        or selected_model_id
        or ""
    )
    template_name = (
        data.get("template_name")
        or first_candidate.get("template_name")
        or selected_model_id
        or ""
    )
    model_description = (
        data.get("model_description")
        or data.get("reason")
        or first_candidate.get("reason")
        or ""
    )

    confidence = _to_float(data.get("confidence", first_candidate.get("score", 0.0)), 0.0)
    if confidence > 1:
        confidence = confidence / 100.0
    confidence = max(0.0, min(confidence, 1.0))

    need_user_confirm = data.get("need_user_confirm")
    if not isinstance(need_user_confirm, bool):
        need_user_confirm = confidence < 0.8 or not selected_model_id or not template_name

    result = {
        "intent": "select_model",
        "selected_model_id": str(selected_model_id),
        "selected_model": str(selected_model),
        "model_description": str(model_description),
        "parameter_requirements": _string_dict(data.get("parameter_requirements")),
        "template_name": str(template_name),
        "numeric": {},
        "text": {},
        "confidence": confidence,
        "need_user_confirm": need_user_confirm,
        "candidates": candidates,
        "retrieval_sources": {
            "knowledge_base": "Jiavu 参数化模型知识库",
            "knowledge_graph": "jiavu",
        },
        "retrieval_signals": signals,
    }

    return {
        "answer": json.dumps(result, ensure_ascii=False, separators=(",", ":"))
    }
